def find_path(graph, start, goal):
    # Record the path length from start to each node
    path_lengths = {start: 0}
    # Records the current path to reach each node
    path_to = {start: [start]}

    # Queue for BFS
    queue = deque([(start, path_to[start], path_lengths[start])])

    while queue:
        current_node, path, length = queue.popleft()

        if current_node == goal:
            return path + [goal]

        for neighbor in graph.get(current_node, []):
            if neighbor not in path_lengths or length + 1 < path_lengths[neighbor]:
                path_lengths[neighbor] = length + 1
                path_to[neighbor] = path + [neighbor]
                queue.append((neighbor, path_to[neighbor], path_lengths[neighbor]))

    # If goal is unreachable
    return None
