def find_path(graph, start, goal):
    """
    Returns a list of nodes from start to goal (inclusive) that follows existing edges,
    or None if goal is unreachable.
    """
    visited = set()
    path = []
    def search(node):
        if node == goal:
            path.append(goal)
            return True
        elif node in visited:
            return False
        visited.add(node)
        path.append(node)
        if node in graph:
            for neighbor in graph[node]:
                if search(neighbor):
                    return True
        path.pop()
        return False

    if start not in graph:
        return None

    search(start)
    if len(path) == 0:
        return None
    else:
        return path
