def find_path(graph, start, goal):
    # Initialize the stack for BFS (using a list as a stack)
    stack = [(start, [start])]
    visited = set()

    while stack:
        (node, path) = stack.pop()
        if node in visited:
            continue
        visited.add(node)

        # If the current node is the goal, return the path
        if node == goal:
            return path

        # Otherwise, explore neighboring nodes
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

    # If no path is found, return None
    return None
