def find_path(graph, start, goal):
    # Initialize open and closed sets
    open_set = set([start])
    came_from = {}

    # Initialize cost and previous nodes
    cost = {start: 0}
    previous = {node: None for node in graph}

    while open_set and goal not in open_set:
        current = None

        # Find the node with the lowest cost
        for node in open_set:
            if current is None or cost[node] < cost[current]:
                current = node

        # If we have found the goal, return the path
        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = previous[current]
            return path[::-1]  # Return reversed path

        # Mark as closed
        open_set.remove(current)
        for neighbor in graph[current]:
            if neighbor not in open_set and neighbor not in cost:
                open_set.add(neighbor)
                cost[neighbor] = cost[current] + 1
                previous[neighbor] = current

    # If we reach here, there is no path
    return None
