def find_path(graph, start, goal):
    # This is a simple implementation of a Breadth-First Search (BFS)
    # to find the shortest path between two nodes in a directed graph.

    if start not in graph or goal not in graph:
        return None

    queue = [(start, [start])]
    while queue:
        (node, path) = queue.pop(0)
        for next_node in graph[node] - set(path):
            if next_node == goal:
                return path + [goal]
            else:
                queue.append((next_node, path + [next_node]))
    return None
