def find_path(graph, start, goal):
    # Track the visited nodes
    visited = set()

    # Track the path from start to goal
    path = []

    # Helper function to do a depth-first search
    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        for neighbor in graph[node]:
            if dfs(neighbor):
                path.append(node)
                return True
        return False

    if dfs(start):
        return path[::-1]  # Reverse the path since we add nodes to the front
    else:
        return None
