def find_path(graph, start, goal):
    # Initialize the path and visited set
    path = []
    visited = set()

    def explore(node):
        # Mark the node as visited
        visited.add(node)
        # If we reach the goal, return the path
        if node == goal:
            return [node]
        for neighbor in graph[node]:
            if neighbor not in visited:
                path_to_neighbor = explore(neighbor)
                if path_to_neighbor:
                    return [node] + path_to_neighbor
        return None

    # Start the exploration from the start node
    return explore(start)
